CREATE TABLE IF NOT EXISTS history_import_batches(id INTEGER PRIMARY KEY, legacy_batch_id INTEGER UNIQUE, filename TEXT NOT NULL, file_hash TEXT, uploaded_at TEXT NOT NULL, snapshot_at TEXT, time_basis TEXT NOT NULL, total_rows INTEGER NOT NULL DEFAULT 0, successful_rows INTEGER NOT NULL DEFAULT 0, new_products INTEGER NOT NULL DEFAULT 0, existing_products INTEGER NOT NULL DEFAULT 0, duplicate_rows INTEGER NOT NULL DEFAULT 0, failed_rows INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, error_details TEXT NOT NULL DEFAULT '[]');
CREATE UNIQUE INDEX IF NOT EXISTS history_file_unique ON history_import_batches(file_hash) WHERE file_hash IS NOT NULL AND status='success';
CREATE TABLE IF NOT EXISTS history_file_fingerprints(file_hash TEXT PRIMARY KEY, import_batch_id INTEGER NOT NULL REFERENCES history_import_batches(id), basis TEXT NOT NULL, recorded_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS history_upload_attempts(id INTEGER PRIMARY KEY,filename TEXT NOT NULL,file_hash TEXT,uploaded_at TEXT NOT NULL,status TEXT NOT NULL,import_batch_id INTEGER,details TEXT);
CREATE TABLE IF NOT EXISTS history_products(id INTEGER PRIMARY KEY, country TEXT NOT NULL, platform_product_id TEXT, fastmoss_product_id TEXT, product_name TEXT, shop_name TEXT, category TEXT, product_url TEXT, fastmoss_url TEXT, image_url TEXT, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS history_products_search ON history_products(country,shop_name,category);
CREATE TABLE IF NOT EXISTS history_identities(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES history_products(id), country TEXT NOT NULL, kind TEXT NOT NULL, value TEXT NOT NULL, basis TEXT NOT NULL, confidence REAL NOT NULL, UNIQUE(country,kind,value));
CREATE TABLE IF NOT EXISTS history_snapshots(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES history_products(id), import_batch_id INTEGER NOT NULL REFERENCES history_import_batches(id), legacy_snapshot_id INTEGER UNIQUE, snapshot_at TEXT, snapshot_date TEXT, observed_at TEXT NOT NULL, time_basis TEXT NOT NULL, sales_7d REAL, gmv_7d REAL, sales_28d REAL, gmv_28d REAL, total_sales REAL, total_gmv REAL, price TEXT, commission_rate REAL, creator_count REAL, creator_sales_rate REAL, promotional_video_count REAL, promotional_livestream_count REAL, product_status TEXT, raw_data_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(product_id,import_batch_id));
CREATE INDEX IF NOT EXISTS history_snapshots_product ON history_snapshots(product_id,observed_at,id);
CREATE TABLE IF NOT EXISTS history_metrics(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES history_products(id), current_snapshot_id INTEGER NOT NULL REFERENCES history_snapshots(id), previous_snapshot_id INTEGER REFERENCES history_snapshots(id), comparison_interval_hours REAL, sales_7d_delta REAL, sales_7d_growth_rate REAL, gmv_7d_delta REAL, gmv_7d_growth_rate REAL, sales_28d_delta REAL, sales_28d_growth_rate REAL, gmv_28d_delta REAL, gmv_28d_growth_rate REAL, price_delta REAL, growth_trend TEXT NOT NULL, calculated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS history_metrics_current ON history_metrics(current_snapshot_id,id DESC);
CREATE TABLE IF NOT EXISTS history_identity_review(id INTEGER PRIMARY KEY, import_batch_id INTEGER REFERENCES history_import_batches(id), legacy_snapshot_id INTEGER, row_number INTEGER, reason TEXT NOT NULL, raw_data_json TEXT NOT NULL, created_at TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS history_review_resolutions(id INTEGER PRIMARY KEY, review_id INTEGER NOT NULL UNIQUE REFERENCES history_identity_review(id), product_id INTEGER NOT NULL REFERENCES history_products(id), decision TEXT NOT NULL, details TEXT NOT NULL, resolved_at TEXT NOT NULL);
